index 0000000..0000000
--- a/dev/null
+++ b/tmp/sv-7823e54874b34eaa8e0a908233636101/UniversityCourseCatalog/Components/Pages/Enroll.razor
@@ -1,0 +1,98 @@
+@page "/enroll"
+@inject UniversityCourseCatalog.Services.CatalogService CatalogService
+
+<PageTitle>Enrollment Request</PageTitle>
+
+<h1>Enrollment Request</h1>
+<p>Submit your enrollment request below. You will receive a confirmation email once processed.</p>
+
+@if (Submitted)
+{
+    <div class="alert alert-success">
+        <h4>Request Submitted!</h4>
+        <p>Your enrollment request has been received. You will be notified once it has been processed.</p>
+        <a href="courses" class="btn btn-primary">Browse More Courses</a>
+    </div>
+}
+else
+{
+    if (ValidationError is not null)
+    {
+        <div class="alert alert-danger">@ValidationError</div>
+    }
+
+    <form method="post" class="col-md-6">
+        <AntiforgeryToken />
+
+        <div class="mb-3">
+            <label for="studentName" class="form-label">Full Name</label>
+            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
+        </div>
+
+        <div class="mb-3">
+            <label for="studentId" class="form-label">Student ID</label>
+            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required placeholder="e.g., S12345678" />
+        </div>
+
+        <div class="mb-3">
+            <label for="courseId" class="form-label">Course</label>
+            <select id="courseId" name="Model.CourseId" class="form-select" required>
+                <option value="0">-- Select a course --</option>
+                @foreach (var course in CatalogService.GetCourses())
+                {
+                    <option value="@course.Id" selected="@(course.Id == Model.CourseId)">@course.CourseCode — @course.Title</option>
+                }
+            </select>
+        </div>
+
+        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
+        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
+    </form>
+}
+
+@code {
+    [SupplyParameterFromForm]
+    public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();
+
+    [SupplyParameterFromQuery]
+    public int? CourseId { get; set; }
+
+    private bool Submitted { get; set; }
+    private string? ValidationError { get; set; }
+
+    protected override void OnInitialized()
+    {
+        if (CourseId.HasValue && Model.CourseId == 0)
+        {
+            Model.CourseId = CourseId.Value;
+        }
+    }
+
+    protected override void OnParametersSet()
+    {
+        // Handle form POST
+        if (HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? ""))
+        {
+            if (string.IsNullOrWhiteSpace(Model.StudentName) ||
+                string.IsNullOrWhiteSpace(Model.StudentId) ||
+                Model.CourseId == 0)
+            {
+                ValidationError = "Please fill in all required fields.";
+                return;
+            }
+
+            if (CatalogService.SubmitEnrollmentRequest(Model))
+            {
+                Submitted = true;
+            }
+            else
+            {
+                ValidationError = "Unable to process your request. Please verify the selected course exists.";
+            }
+        }
+    }
+
+    [CascadingParameter]
+    public HttpContext? HttpContextAccessor { get; set; }
+}
+

